package com.company.platform.administration.infrastructure;
import java.util.*;import org.springframework.context.annotation.*;import org.springframework.core.convert.converter.Converter;import org.springframework.security.authentication.AbstractAuthenticationToken;import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationConverter;import org.springframework.security.web.SecurityFilterChain;
@Configuration @EnableMethodSecurity public class SecurityConfiguration{@Bean SecurityFilterChain security(HttpSecurity h,Converter<Jwt,AbstractAuthenticationToken> jwt)throws Exception{return h.csrf(c->c.disable()).authorizeHttpRequests(a->a.requestMatchers("/actuator/health","/actuator/info").permitAll().anyRequest().authenticated()).oauth2ResourceServer(o->o.jwt(j->j.jwtAuthenticationConverter(jwt))).build();}@Bean Converter<Jwt,AbstractAuthenticationToken> jwtAuthenticationConverter(){var c=new JwtAuthenticationConverter();c.setJwtGrantedAuthoritiesConverter(jwt->{var a=new ArrayList<org.springframework.security.core.GrantedAuthority>();for(String claim:List.of("roles","permissions")){var v=jwt.getClaimAsStringList(claim);if(v!=null)v.forEach(x->a.add(new org.springframework.security.core.authority.SimpleGrantedAuthority(x)));}var r=jwt.getClaim("realm_access");if(r instanceof Map<?,?> m&&m.get("roles") instanceof Collection<?> v)v.forEach(x->a.add(new org.springframework.security.core.authority.SimpleGrantedAuthority("ROLE_"+x)));return a;});return c;}}
